.wssmartjacket__pus{color:#876f1e}.wssmartjacket__plavo{background:#876f1e;margin-top:-72px}.wssmartjacket__k--temna{background:#876f1e}
@media (max-width:860px){.wssmartjacket__s{padding:46px 0}.wssmartjacket__s.wssmartjacket__traka{padding:30px 0}.wssmartjacket__plavo{margin-top:-46px}.wssmartjacket__pog>div{padding:22px 12px}}
@media (max-width:767px){.wssmartjacket__v{padding:0 16px}}
/* /dizajn.py */
/* brez-obrob */ .wssmartjacket__av,.wssmartjacket__k,.wssmartjacket__media,.wssmartjacket__pog>div,.wssmartjacket__polna,span.wssmartjacket__pi{border:0!important}
/* Kartica samo z medijem (brez napisa): brez belega pasu pod videom/sliko - samo medij z zaobljenimi robovi (Dejan 26.10.2026). */
.wssmartjacket__kt:empty{display:none}.wssmartjacket__k:has(>.wssmartjacket__kt:empty){background:transparent;border:0;box-shadow:none}.wssmartjacket__k:has(>.wssmartjacket__kt:empty):hover{box-shadow:none}
</style>
<script>
(function(){document.querySelectorAll('.wssmartjacket__kar').forEach(function(k){
  var w=document.createElement('div');w.className='wssmartjacket__karw';k.parentNode.insertBefore(w,k);w.appendChild(k);
  ['l','d'].forEach(function(s){var b=document.createElement('button');b.type='button';b.className='wssmartjacket__pus wssmartjacket__pus--'+s;b.setAttribute('aria-label',s==='l'?'Prethodno':'Sljedeće');b.innerHTML=s==='l'?'&#8249;':'&#8250;';
    b.addEventListener('click',function(){var x=k.firstElementChild;var d=x?x.getBoundingClientRect().width+22:300;k.scrollBy({left:s==='l'?-d:d,behavior:'smooth'});});w.appendChild(b);});
});})();
</script>
